import pytest

from mastery import CourseGraph, ProgressTracker


def build_chain_graph():
    """A richer DAG to exercise ordering and determinism."""
    g = CourseGraph()
    courses = [
        "intro", "algebra", "geometry", "trig",
        "algebra2", "calc", "stats",
    ]
    for c in courses:
        g.add_course(c)
    g.add_prereq("algebra2", "algebra")
    g.add_prereq("algebra2", "geometry")
    g.add_prereq("trig", "algebra2")
    g.add_prereq("calc", "trig")
    g.add_prereq("stats", "algebra")
    return g


class TestMasteryPath:
    @pytest.mark.parametrize("target", ["calc", "stats", "algebra2", "intro"])
    def test_is_valid_topological_order(self, target):
        g = build_chain_graph()
        t = ProgressTracker(g)
        path = t.mastery_path(target)

        assert path[-1] == target                       # target last
        assert len(path) == len(set(path))              # no repeats
        assert set(path) <= g.courses

        position = {c: i for i, c in enumerate(path)}
        for course in path:
            for prereq in g.prerequisites(course):
                if prereq in position:
                    assert position[prereq] < position[course]

    def test_includes_all_transitive_prereqs(self):
        g = build_chain_graph()
        path = set(ProgressTracker(g).mastery_path("calc"))
        # calc <- trig <- algebra2 <- {algebra, geometry} <- intro? no:
        # transitive prereqs of calc are trig, algebra2, algebra, geometry.
        assert path == {"calc", "trig", "algebra2", "algebra", "geometry"}

    def test_determinism_across_repeated_calls(self):
        g = build_chain_graph()
        t = ProgressTracker(g)
        first = t.mastery_path("calc")
        for _ in range(20):
            assert t.mastery_path("calc") == first

    def test_determinism_across_insertion_orders(self):
        edges = [("algebra2", "algebra"), ("algebra2", "geometry"),
                 ("trig", "algebra2"), ("calc", "trig")]
        baseline = None
        for permutation in (edges, list(reversed(edges)), [edges[2], edges[0], edges[3], edges[1]]):
            g = CourseGraph()
            for course in ("intro", "algebra", "geometry", "trig", "algebra2", "calc"):
                g.add_course(course)
            for e in permutation:
                g.add_prereq(*e)
            path = ProgressTracker(g).mastery_path("calc")
            if baseline is None:
                baseline = path
            else:
                assert path == baseline

    def test_ties_broken_alphabetically(self):
        g = CourseGraph()
        for c in ("zeta_root", "alpha_root", "middle", "target"):
            g.add_course(c)
        # Two independent prereqs of 'target': alpha_root < zeta_root wins.
        g.add_prereq("target", "zeta_root")
        g.add_prereq("target", "alpha_root")
        g.add_prereq("middle", "target")
        path = ProgressTracker(g).mastery_path("middle")
        assert path == ["alpha_root", "zeta_root", "target", "middle"]

    def test_unknown_target_raises(self):
        with pytest.raises(KeyError):
            ProgressTracker(CourseGraph()).mastery_path("nope")

